fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "--"

    val seconds = exposureTimeNs / 1_000_000_000.0

    if (seconds >= 0.5) {
        val rounded = (seconds * 100.0).roundToInt() / 100.0
        return if (rounded % 1.0 == 0.0) {
            "${rounded.toLong()}s"
        } else {
            java.text.DecimalFormat("0.##", java.text.DecimalFormatSymbols(java.util.Locale.US))
                .format(rounded) + "s"
        }
    }

    val denominator = (1_000_000_000.0 / exposureTimeNs).roundToInt()
    return if (denominator <= 1) "1s" else "1/${denominator}s"
}

