{"command": "cd /home/agent/workspace && cat > /tmp/detect.py <<'EOF'
import numpy as np
from PIL import Image
import glob, os

def gauss(f, sigma=1.0, radius=None):
    if radius is None: radius = max(1, int(3*sigma))
    x = np.arange(-radius, radius+1)
    k = np.exp(-x**2/(2*sigma**2)); k /= k.sum()
    # pad reflect then separable conv via tensordot-free slicing
    def c1d(a, axis):
        n = a.shape[axis]
        pad = [(0,0)]*a.ndim
        pad[axis] = (radius, radius)
        p = np.pad(a, pad, mode='reflect')
        out = np.zeros_like(a)
        for i, w in enumerate(k):
            sl = [slice(None)]*a.ndim
            sl[axis] = slice(i, i+n)
            out += w*p[tuple(sl)]
        return out
    return c1d(c1d(f, 0), 1)

def ddx(f):  # central difference along columns (x)
    return np.pad(f[:,2:]-f[:,:-2], ((0,0),(1,1)), mode='edge')
def ddy(f):  # central difference along rows (y, downward)
    return np.pad(f[2:,:]-f[:-2,:], ((1,1),(0,0)), mode='edge')

def analyse(path, sigma=1.0):
    a = np.asarray(Image.open(path).convert('RGB'), dtype=np.float32)/255.0
    R = gauss(a[...,0]-0.5, sigma); G = gauss(a[...,1]-0.5, sigma)
    A = ddy(R); B = ddx(G)          # A = dFx/drow, B = dFy/dcol  (curl = B - A)
    m = (np.abs(R)+np.abs(G)) > 0.01
    A, B = A[m], B[m]
    Ac = A-A.mean(); Bc = B-B.mean()
    corr = (Ac*Bc).mean()/np.sqrt((Ac*Ac).mean()*(Bc*Bc).mean()+1e-12)
    return corr, ((A-B)**2).mean(), ((A+B)**2).mean()

if __name__=='__main__':
    for f in sorted(glob.glob('textures/*.png')):
        c, ep, em = analyse(f)
        print(f"{os.path.basename(f):40s} corr={c:+.3f} |curl_ogl|={ep:.3e} |curl_d3d|={em:.3e} -> {'OGL' if c>0 else 'D3D'}")
EOF
